"""Render the curated JSON as a portable, offline-searchable reference library."""
import html
import json
from pathlib import Path

root = Path(__file__).parent
library = json.loads((root / 'library.json').read_text())
refs = library['references']
categories = list(dict.fromkeys(r['category'] for r in refs))
def esc(value):
    return html.escape(str(value), quote=True)

cards = []
for r in refs:
    launch = f'<a href="{esc(r["experience"])}" target="_blank" rel="noopener noreferrer">Experience link ↗</a>' if r['experience'] else ''
    cards.append(f'''<article class="card" data-category="{esc(r['category'])}" data-start="{str(r['start']).lower()}" data-scope="{esc(r['scope'])}" data-search="{esc(' '.join(str(v) for v in r.values()).lower())}">
      <div class="cardtop"><span class="number">{r['id']:02}</span><span>{esc(r['category'])}</span>{'<span class="pick">Start here</span>' if r['start'] else ''}</div>
      <h2>{esc(r['name'])}</h2><p class="creator">{esc(r['creator'])}</p>
      <p class="action">{esc(r['action'])}</p>
      <div class="insight"><h3>What makes it worth studying</h3><p>{esc(r['appeal'])}</p></div>
      <details><summary>Pattern to borrow + what it takes</summary><h3>Pattern to borrow</h3><p>{esc(r['borrow'])}</p><h3>What it takes / where it breaks</h3><p>{esc(r['dependency'])}</p></details>
      <footer><span class="tag">{esc(r['scope'])}</span><span class="evidence">{esc(r['evidence'])}</span><nav aria-label="Sources for {esc(r['name'])}"><a href="{esc(r['source'])}" target="_blank" rel="noopener noreferrer">{'View reference' if r['evidence'] in ('Product page', 'One round tried', 'Creator page') and not r['experience'] else 'Read source'} ↗</a>{launch}</nav></footer>
    </article>''')
options = ''.join(f'<option>{esc(c)}</option>' for c in categories)
scopes = ''.join(f'<option>{esc(s)}</option>' for s in sorted(set(r['scope'] for r in refs)))
page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>60 ways to earn attention — Recoup reference library</title>
<style>
:root{--paper:#f4f0e8;--ink:#272523;--muted:#69625a;--accent:#59394b;--line:#d9d1c6;--card:#fffdf8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 ui-sans-serif,system-ui,-apple-system,sans-serif}a{color:var(--accent);text-underline-offset:4px}button,input,select{font:inherit}button,select,summary{cursor:pointer}:focus-visible{outline:3px solid #a3581f;outline-offset:4px}.wrap{max-width:1440px;margin:auto;padding:0 42px}.mast{display:flex;justify-content:space-between;padding:25px 0;box-shadow:0 1px var(--line);font-size:12px;letter-spacing:.12em;text-transform:uppercase}.hero{padding:65px 0 40px;display:grid;grid-template-columns:1fr 180px;gap:40px}.eyebrow{color:var(--accent);text-transform:uppercase;letter-spacing:.14em;font-size:12px;font-weight:700}h1{font:clamp(46px,6vw,88px)/1.03 Georgia,serif;letter-spacing:-.045em;max-width:850px;margin:18px 0 25px}.intro{max-width:780px;font-size:19px;color:var(--muted)}.count{font:140px/1 Georgia,serif;letter-spacing:-.09em;color:var(--accent);text-align:right}.count small{display:block;font:12px/1.6 system-ui;letter-spacing:.13em;text-transform:uppercase;margin-top:12px}.note{max-width:1000px;color:var(--muted);font-size:13px}.paths{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin:25px 0 40px}.path{box-shadow:inset 0 2px var(--accent);padding-top:14px}.path h2{font:23px/1.2 Georgia,serif;margin:4px 0 12px}.path p{font-size:14px;color:var(--muted);margin:0}.toolbar{background:var(--paper);padding:20px 0 16px;box-shadow:0 -1px var(--line),0 1px var(--line)}.filters{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px}label{display:block;font-size:12px;letter-spacing:.02em;color:var(--muted)}input,select{display:block;width:100%;margin-top:5px;min-height:46px;padding:9px 12px;background:var(--card);border:0;border-radius:4px;box-shadow:0 0 0 1px var(--line);color:var(--ink)}.tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:15px}button{border:0;border-radius:30px;padding:8px 15px;color:var(--ink);background:#e6ded4}button[aria-pressed=true]{background:var(--accent);color:white}.result{margin-left:auto;font-size:13px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;padding:28px 0 50px}.card{display:flex;flex-direction:column;padding:25px;background:var(--card);border-radius:5px;box-shadow:0 0 0 1px #e4ddd3,0 3px 12px #38291a05}.card[hidden]{display:none}.cardtop{font-size:10px;letter-spacing:.05em;text-transform:uppercase;display:flex;align-items:center;gap:9px;color:var(--muted)}.number{font:italic 20px Georgia;color:var(--accent)}.pick{margin-left:auto;background:#eee6eb;padding:3px 6px;border-radius:3px;color:var(--accent)}.card h2{font:29px/1.13 Georgia,serif;letter-spacing:-.025em;margin:18px 0 6px}.creator{font-size:12px;color:var(--muted);margin:0 0 15px}.action{font-size:15px;margin:0 0 18px}.insight{background:#f2eee7;padding:14px 16px;margin-bottom:17px}.card h3{font-size:10px;text-transform:uppercase;letter-spacing:.09em;color:var(--accent);margin:0 0 6px}.insight p,details p{font-size:13px;margin:0}details{font-size:12px;margin-bottom:20px}summary{font-weight:600;line-height:1.5}details h3{margin-top:15px!important}footer{margin-top:auto;font-size:11px}.tag{display:inline-block;background:#ede9e2;padding:3px 7px;border-radius:4px}.evidence{display:block;color:var(--muted);margin:9px 0}footer nav{display:flex;gap:14px;flex-wrap:wrap;font-size:12px}.empty{padding:50px;font-size:22px;text-align:center}.end{padding:25px 0 50px;box-shadow:0 -1px var(--line);font-size:13px;color:var(--muted);max-width:950px}.end h2{font:28px Georgia;color:var(--ink)}.end li{margin-bottom:8px}@media(max-width:1100px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.paths{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.wrap{padding:0 20px}.hero{grid-template-columns:1fr;padding-top:35px;gap:0}.count{display:none}.mast{font-size:10px}.grid{grid-template-columns:1fr}.filters{grid-template-columns:1fr}.paths{gap:20px}h1{font-size:49px}.intro{font-size:17px}.card{padding:22px}.result{margin-left:0;width:100%}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}@media print{.toolbar{display:none}.grid{display:block}.card{break-inside:avoid;margin-bottom:20px}.card[hidden]{display:block}.hero{padding:20px 0}.paths{display:none}a{color:inherit}}
</style></head><body><div class="wrap"><header class="mast"><span>Recoup / Field notes 001</span><span>Reference collection · 28 Sep 2026</span></header>
<section class="hero"><div><div class="eyebrow">Play / Make / Discover / Belong</div><h1>60 ways to<br>earn attention.</h1><p class="intro">A broad collection of digital experiences worth studying. Games, creative toys, brand worlds, personal stories and collective experiments—organized around what people actually do.</p><p class="note">Research candidates, not approved templates. “Worth studying” is our design interpretation, not a measured ranking of engagement. Product pages and historical case studies are labeled; a surviving source does not establish that an old experience still runs.</p></div><div class="count">60<small>References<br>10 categories</small></div></section>
<section class="paths" aria-label="Suggested routes through the collection"><div class="path"><h2>Make the first touch count.</h2><p>Start with Perfect Circle, Patatap, Quick, Draw! and XOX. Compare rules, feedback and the desire to try again.</p></div><div class="path"><h2>Give people something worth making.</h2><p>Compare Silk, Townscaper, Incredibox and See Yourself in Sound. The reward is the creation itself.</p></div><div class="path"><h2>Make participation matter.</h2><p>Study Gartic Phone, Your Line or Mine and Puff Up Club. Another person changes the experience.</p></div><div class="path"><h2>Reward curiosity.</h2><p>Explore Radio Garden, MoMA Magritte, A Dark Room and The Pudding. Each action reveals a reason to continue.</p></div></section>
<section class="toolbar" aria-label="Filter references"><div class="filters"><label>Find a reference, action or idea<input id="search" type="search" placeholder="Try drawing, personal, puzzle, sound…"></label><label>Category<select id="category"><option value="">All categories</option>__CATEGORIES__</select></label><label>Production shape<select id="scope"><option value="">All production shapes</option>__SCOPES__</select></label></div><div class="tools"><button id="starter" type="button" aria-pressed="false">Start here selections</button><button id="reset" type="button">Clear filters</button><span id="result" class="result" role="status" aria-live="polite">60 references</span></div></section>
<main><div id="grid" class="grid">__CARDS__</div><p id="empty" class="empty" hidden>No references match. Try a broader search or clear the filters.</p></main>
<section class="end"><h2>Use the collection to develop taste.</h2><p>These are starting points for comparison, not instructions to copy. Keep the interaction, its content and its execution separate when discussing what works.</p><ol><li>Try a reference or watch the creator’s demonstration. Judge the first action and what it produces.</li><li>Mark what you would keep, reject or borrow—and name the specific part.</li><li>Compare an obvious, well-executed interaction with an ambitious one. Complexity is neither a requirement nor a disqualification.</li><li>Only then decide whether a reusable foundation would preserve the part you liked.</li></ol><p><strong>Research method:</strong> Creator, publisher, brand and product sources were reviewed. One round of Absurd Trolley Problems was tried; the other experiences were researched from their pages and documentation, not end-to-end playtested. No campaign performance numbers are used as independent proof of quality. Scope labels and adaptation notes are our assessments, not capability claims about the current Sites engine.</p><p><a href="README.md">Research synthesis</a> · <a href="library.json">Structured reference data</a> · All external sources open in a new tab. No sign-in, analytics or remote scripts are used by this library.</p></section></div>
<script>
const cards=[...document.querySelectorAll('.card')];
const search=document.getElementById('search'), category=document.getElementById('category'), scope=document.getElementById('scope'), starter=document.getElementById('starter');
function filter(){const q=search.value.trim().toLowerCase();let total=0;for(const card of cards){const show=(!q||card.dataset.search.includes(q))&&(!category.value||card.dataset.category===category.value)&&(!scope.value||card.dataset.scope===scope.value)&&(starter.getAttribute('aria-pressed')!=='true'||card.dataset.start==='true');card.hidden=!show;if(show)total++;}document.getElementById('result').textContent=`${total} of ${cards.length} references`;document.getElementById('empty').hidden=total!==0;}
search.addEventListener('input',filter);category.addEventListener('change',filter);scope.addEventListener('change',filter);starter.addEventListener('click',()=>{starter.setAttribute('aria-pressed',String(starter.getAttribute('aria-pressed')!=='true'));filter();});document.getElementById('reset').addEventListener('click',()=>{search.value='';category.value='';scope.value='';starter.setAttribute('aria-pressed','false');filter();});
</script></body></html>'''
page = page.replace('__CATEGORIES__', options).replace('__SCOPES__', scopes).replace('__CARDS__', '\n'.join(cards))
(root / 'index.html').write_text(page)
print(f'Rendered {len(refs)} references across {len(categories)} categories; {sum(r["start"] for r in refs)} starter selections.')
